public class TLABAllocationDemo {
    // Under the hood, executing this loop heavily leverages TLAB.
    // Millions of objects are allocated concurrently by multiple threads
    // without ever acquiring a global heap lock.
    public static void main(String[] args) {
        Runnable task = () -> {
            for (int i = 0; i < 1_000_000; i++) {
                DataHolder holder = new DataHolder(i, "Payload-" + i);
            }
        };

        new Thread(task).start();
        new Thread(task).start();
    }

    private static class DataHolder {
        private final int id;
        private final String data;
        public DataHolder(int id, String data) {
            this.id = id;
            this.data = data;
        }
    }
}
